        <style>{`.login-mark,.brand-mark{position:relative;overflow:hidden;background:linear-gradient(145deg,#27b9db,#1479de)!important;box-shadow:0 5px 12px #0d6da844}.login-mark:before,.brand-mark:before{content:"";position:absolute;left:7px;top:9px;width:17px;height:8px;border-top:2px solid #fff;border-radius:50%;transform:skewX(-18deg)}.login-mark:after,.brand-mark:after{content:"";position:absolute;left:9px;top:15px;width:14px;height:7px;border-top:2px solid #d6fbff;border-radius:50%;transform:skewX(-18deg)}`}</style>
        {signupOpen && <div className="signup-backdrop" role="dialog" aria-modal="true"><section className="signup-modal"><button onClick={() => setSignupOpen(false)} aria-label="닫기">×</button><p>WAVEMAP JOIN</p><h2>간단히 시작해 보세요.</h2><input aria-label="이름" placeholder="이름" /><input aria-label="이메일" type="email" placeholder="이메일" /><label><input type="checkbox" /> 서비스 이용 약관에 동의합니다.</label><button className="signup-submit" onClick={() => setSignupOpen(false)}>회원가입 완료</button><small>회원가입 후 맞춤 해변 추천을 이용할 수 있습니다.</small></section></div>}
