        <style>{`.login-page{grid-template-columns:minmax(420px,46%) 1fr;background:#062a3d}.login-card{max-width:none;padding:8vw;background:radial-gradient(circle at 5% 5%,#176789 0,transparent 30%),linear-gradient(160deg,#082a3d,#071e30 76%);color:#fff}.login-brand{color:#fff}.login-mark{background:#31b6dd;box-shadow:0 0 0 6px #31b6dd22}.login-kicker{margin-top:52px;color:#7be6ff;letter-spacing:1.5px}.login-card h1{color:#fff;font-size:clamp(38px,4.5vw,58px);letter-spacing:-3.4px}.login-card h1 em{color:#81e4f5}.login-copy{color:#b8d2dd}.login-preview{border-color:#ffffff26;background:#ffffff12;color:#d6edf4}.login-button{position:relative;overflow:hidden;background:linear-gradient(100deg,#25a9cf,#3dcfbc);box-shadow:0 14px 28px #001b2d66}.login-button:before{content:"";position:absolute;inset:0;background:linear-gradient(120deg,transparent 35%,#ffffff33 50%,transparent 65%);transform:translateX(-100%);transition:.4s}.login-button:hover:before{transform:translateX(100%)}.login-card>small{color:#82a7b6}.login-stats{border-color:#ffffff24;background:#ffffff0d}.login-stats span{border-color:#ffffff1c;color:#a8c7d2}.login-stats b{color:#7be6ff}.login-features span{background:#ffffff10;color:#bcd8e1}.login-features i{color:#7be6ff}.login-scene{background:radial-gradient(circle at 75% 18%,#ffe9a7 0 8%,transparent 8.5%),linear-gradient(150deg,#80d4e8 0%,#caeff0 49%,#f3d999 49.5%,#e9c67e 100%)}.login-ocean{inset:0 0 42% 0;background:repeating-linear-gradient(175deg,transparent 0 28px,#ffffff55 29px 31px),linear-gradient(135deg,#168db7a8,#79d6df8a)}.login-sand{height:50%;background:repeating-linear-gradient(160deg,#ecd293 0 15px,#f4e1ae 16px 32px)}.login-sun{display:none}.scene-eyebrow{right:38px;background:#09344bcc;border-color:#ffffff55}.scene-live-card{top:23%;left:12%;border:0;background:#fff;box-shadow:0 18px 40px #1760782e}.scene-route-card{right:9%;bottom:16%;border:0;background:#07364edb;color:#fff}.scene-route-card span{color:#8ae7d2}.scene-route-card b{color:#fff}.scene-route-card small{color:#c5e2e8}.login-pin{border-color:#fff8;box-shadow:0 8px 23px #12445d55}.pin-one{right:39%;bottom:30%}.pin-two{right:16%;bottom:43%}@media(max-width:720px){.login-page{background:#08283a}.login-card{padding:54px 28px}.login-card h1{font-size:39px}.login-details{margin-top:17px}.scene-live-card,.scene-route-card{display:none}}`}</style>
